package com.tdc.nhom6.doanjava1.controller;
import com.tdc.nhom6.doanjava1.model.Account;import com.tdc.nhom6.doanjava1.service.*;import javax.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.util.*;
@Controller @RequestMapping("/admin") public class AdminController {
 private final AccountService accounts;private final BorrowService borrows;private final BookService books;
 public AdminController(AccountService a,BorrowService b,BookService k){accounts=a;borrows=b;books=k;}
 private Account current(HttpSession s){return (Account)s.getAttribute("currentUser");}
 @GetMapping("/users") public String users(HttpSession s,Model m){Account a=current(s);if(a==null||!a.canManage())return "redirect:/books";m.addAttribute("account",a);m.addAttribute("users",accounts.findAll());return "admin/users";}
 @GetMapping("/users/{id}/history") public String userHistory(@PathVariable Long id,HttpSession s,Model m){Account a=current(s);if(a==null||!a.canManage())return "redirect:/books";m.addAttribute("account",a);m.addAttribute("targetUser",accounts.findById(id));m.addAttribute("records",borrows.findByAccount(id));return "admin/user-history";}
 @PostMapping("/users/{id}/promote") public String promote(@PathVariable Long id,HttpSession s,RedirectAttributes ra){if(current(s)==null||!current(s).isAdmin())return "redirect:/books";try{accounts.promote(id);ra.addFlashAttribute("success","Đã thăng cấp!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/users";}
 @PostMapping("/users/{id}/demote") public String demote(@PathVariable Long id,HttpSession s,RedirectAttributes ra){if(current(s)==null||!current(s).isAdmin())return "redirect:/books";try{accounts.demote(id);ra.addFlashAttribute("success","Đã hạ cấp!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/users";}
 @PostMapping("/users/{id}/delete") public String disable(@PathVariable Long id,HttpSession s,RedirectAttributes ra){if(current(s)==null||!current(s).isAdmin())return "redirect:/books";try{accounts.delete(id);ra.addFlashAttribute("success","Đã vô hiệu hóa tài khoản!");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/users";}
 @GetMapping("/stats") public String stats(HttpSession s,Model m){Account a=current(s);if(a==null||!a.canManage())return "redirect:/books";int total=books.findAll().stream().mapToInt(b->b.getTotalCopies()).sum(),avail=books.findAll().stream().mapToInt(b->b.getAvailableCopies()).sum();Map<String,Object> inventory=new HashMap<>();inventory.put("totalTitles",books.findAll().size());inventory.put("totalCopies",total);inventory.put("availableCopies",avail);inventory.put("borrowedCopies",total-avail);Map<String,Object> monthly=new HashMap<>();monthly.put("month",java.time.YearMonth.now().toString());monthly.put("totalBorrows",borrows.countBorrowedThisMonth());monthly.put("totalReturns",borrows.countReturnedThisMonth());monthly.put("currentOverdue",borrows.findOverdue().size());Map<String,Object> revenue=new HashMap<>();revenue.put("totalFinesCollected",borrows.finesCollected());m.addAttribute("account",a);m.addAttribute("inventory",inventory);m.addAttribute("monthly",monthly);m.addAttribute("revenue",revenue);m.addAttribute("mostBorrowed",borrows.mostBorrowed(10));m.addAttribute("overdueCount",borrows.findOverdue().size());return "admin/stats";}
}